// puzzle-fixtures.mjs - Loader for the generated puzzle fixture set.
//
// Fixtures are generated by scripts/generate-puzzle-fixtures.mjs into
// puzzle-fixtures.generated.mjs. Each fixture's initialState is represented
// canonically as (profileId + seed + setupCommands) and reconstructed at load
// time through the real engine (see reconstructInitialState in
// puzzle-runtime.mjs).

import fixturesGenerated from './puzzle-fixtures.generated.mjs';

/**
 * @returns {import('./puzzle-types.mjs').PuzzleDefinition[]}
 */
export function listPuzzleDefinitions() {
  return [...fixturesGenerated.fixtures];
}

/**
 * @param {string} id
 * @returns {import('./puzzle-types.mjs').PuzzleDefinition|null}
 */
export function getPuzzleDefinition(id) {
  return fixturesGenerated.fixtures.find((f) => f.id === id) ?? null;
}

export const PUZZLE_FIXTURES_SCHEMA_VERSION = fixturesGenerated.schemaVersion;
